example:
agent Tally {
    key id: String
    store count: Cell[Int]

    on call get() -> Effect[Result[Int, String]] {
        Ok(count)
    }

    invariant nonNegative: count >= 0                // ✗ after a handler
}

agent Tally {
    key id: String
    store count: Cell[Int]

    invariant nonNegative: count >= 0                // ✓ before the handlers

    on call get() -> Effect[Result[Int, String]] {
        Ok(count)
    }
}
